use super::*;
use crate::ir::Contract;
use crate::{RenderError, render_with_capabilities};
use serde_json::{Value, json};

fn fixture(name: &str) -> Value {
    let text = match name {
        "flat" => include_str!("../../../../tests/unit-composition/flat.json"),
        "chunked" => include_str!("../../../../tests/unit-composition/chunked.json"),
        "crypto" => include_str!("../../../../tests/unit-composition/crypto.json"),
        "guard" => include_str!("../../../../tests/set-composition/pure_unit_guard.json"),
        "zswap" => include_str!("../../../../tests/native-zswap-intents-schema18-ir.json"),
        _ => unreachable!(),
    };
    serde_json::from_str(text).unwrap()
}
fn circuit<'a>(v: &'a mut Value, name: &str) -> &'a mut Value {
    v["stateful_circuits"]
        .as_array_mut()
        .unwrap()
        .iter_mut()
        .find(|c| c["name"] == name)
        .unwrap()
}
fn attempt(value: Value, name: &str) -> ProfileAttempt<TypedPlan, CompositionRejection> {
    let c: Contract = serde_json::from_value(value).unwrap();
    let ledger = c.ledger_fields.iter().map(|x| (x.id.as_str(), x)).collect();
    let witnesses = c.witnesses.iter().map(|x| (x.name.as_str(), x)).collect();
    let pure = c.circuits.iter().map(|x| (x.name.as_str(), x)).collect();
    let circuits: HashMap<_, _> = c
        .stateful_circuits
        .iter()
        .map(|x| (x.name.as_str(), x))
        .collect();
    lower_checked(circuits[name], &ledger, &witnesses, &pure, &circuits)
}
fn rejected(value: Value, name: &str) -> CompositionRejection {
    match attempt(value, name) {
        ProfileAttempt::Rejected(r) => r,
        ProfileAttempt::Admitted(_) => panic!("incomplete/rejected domain escaped as a plan"),
        ProfileAttempt::NotApplicable => panic!("expected a matched Unit candidate"),
    }
}
fn unsupported() -> Value {
    json!({"kind":"expression","value":{"kind":"kernel_self","ty":{"kind":"struct","name":"ContractAddress","fields":[{"name":"bytes","ty":{"kind":"bytes","length":32}}]}}})
}

#[test]
fn signatures_are_unrelated_but_complete_helper_domains_are_admitted() {
    for name in ["flat", "chunked", "crypto"] {
        assert!(matches!(
            attempt(fixture(name), "close"),
            ProfileAttempt::Admitted(_)
        ));
    }
    for name in ["run", "local_control", "transitive_control"] {
        assert!(matches!(
            attempt(fixture("guard"), name),
            ProfileAttempt::Admitted(_)
        ));
    }
    for mutation in ["result", "return", "parameter"] {
        let mut v = fixture("flat");
        let c = circuit(&mut v, "close");
        match mutation {
            "result" => c["result"] = json!({"kind":"field"}),
            "return" => c["return_value"] = json!({"kind":"expression","value":{"kind":"unit"}}),
            _ => {
                c["parameters"][0]["ty"] =
                    json!({"kind":"unsigned","max":"340282366920938463463374607431768211455"})
            }
        }
        assert!(
            matches!(attempt(v, "close"), ProfileAttempt::NotApplicable),
            "{mutation}"
        );
    }
}

#[test]
fn final_obligations_distinguish_no_effect_from_missing_helper() {
    let mut v = fixture("flat");
    circuit(&mut v, "close")["actions"] = json!([]);
    let r = rejected(v, "close");
    assert_eq!(
        r.gap.code,
        super::super::super::RecordingGapCode::NoRecordedEffect
    );
    assert_eq!(r.phase, RejectionPhase::FinalObligation);
    assert_eq!(r.root_action, None);
    let mut v = fixture("flat");
    circuit(&mut v, "close")["actions"] = json!([{"kind":"cell_write","field":"active","index":0,"value":{"kind":"boolean","value":false}}]);
    let r = rejected(v, "close");
    assert_eq!(
        r.gap.code,
        super::super::super::RecordingGapCode::RecordingUnavailable
    );
    assert!(r.gap.detail.contains("Unit helper"));
}

#[test]
fn unselected_checked_effect_is_supported_but_unsupported_effect_keeps_legacy_precision() {
    for retain_earlier_guard in [false, true] {
        let mut v = fixture("flat");
        if !retain_earlier_guard {
            circuit(&mut v, "guard")["actions"] = json!([]);
        }
        circuit(&mut v, "guard")["actions"]
            .as_array_mut()
            .unwrap()
            .push(json!({
                "kind":"if","condition":{"kind":"boolean","value":true},
                "then":{"kind":"sequence","actions":[]},"otherwise":unsupported()
            }));
        let r = rejected(v.clone(), "close");
        assert_eq!(r.root_action, Some(0));
        assert_eq!(r.precision, RejectionPrecision::ConcreteNode);
        let index = usize::from(retain_earlier_guard);
        assert_eq!(
            r.gap.path,
            format!("actions[0].callee[\"guard\"].actions[{index}].otherwise")
        );
        // The old composition audit remains an independent refusal oracle.
        // Checked statement calls now retain KernelSelf even in an unselected arm.
        let c: Contract = serde_json::from_value(v.clone()).unwrap();
        let result = render_with_capabilities(&c).unwrap();
        let capability = result
            .capabilities
            .circuits
            .iter()
            .find(|x| x.name == "close")
            .unwrap();
        assert!(capability.recorded && capability.observed_call);
        assert!(capability.recording_unavailable.is_none());
        let recording = result.source.split("pub mod recorded").nth(1).unwrap();
        assert!(recording.contains("kernel_self()"));

        // The old shape audit still refuses a native-key observation, but
        // checked composition now supports it as an ordered private effect.
        circuit(&mut v, "guard")["actions"][index]["otherwise"] = json!({
            "kind":"native_witness_call", "builtin":"own_public_key"
        });
        let still_rejected = rejected(v.clone(), "close");
        assert_eq!(still_rejected.gap.path, r.gap.path);
        let c: Contract = serde_json::from_value(v.clone()).unwrap();
        let result = render_with_capabilities(&c).unwrap();
        let capability = result
            .capabilities
            .circuits
            .iter()
            .find(|x| x.name == "close")
            .unwrap();
        assert!(capability.recorded && capability.observed_call);
        assert!(
            result
                .source
                .split("pub mod recorded")
                .nth(1)
                .unwrap()
                .contains("own_coin_public_key()?")
        );

        // Keep the former refusal as an explicit checked-composition gain:
        // the old auditor still rejects private-key operands inside inequality.
        let observed_key = json!({"kind":"native_witness_call", "builtin":"own_public_key"});
        circuit(&mut v, "guard")["actions"][index]["otherwise"] = json!({
            "kind":"expression", "value": {
                "kind":"not_equal", "left":observed_key.clone(), "right":observed_key
            }
        });
        let still_rejected = rejected(v.clone(), "close");
        assert_eq!(still_rejected.gap.path, r.gap.path);
        let c: Contract = serde_json::from_value(v.clone()).unwrap();
        let result = render_with_capabilities(&c).unwrap();
        let capability = result
            .capabilities
            .circuits
            .iter()
            .find(|x| x.name == "close")
            .unwrap();
        assert!(capability.recorded && capability.observed_call);
        assert!(capability.recording_unavailable.is_none());

        // A literal-only hash would make the helper locally auditable. Retain
        // the private key observation so the whole legacy composition root
        // refuses this arm, independently of the newly supported checked Keccak.
        circuit(&mut v, "guard")["actions"][index]["otherwise"] = json!({
            "kind":"expression", "value": {
                "kind":"equal", "left": {
                    "kind":"keccak256", "value":{
                        "kind":"struct_field", "value":observed_key.clone(),
                        "field":"bytes", "index":0
                    }
                }, "right":{"kind":"bytes_literal","bytes":vec![0u8; 32]}
            }
        });
        let still_rejected = rejected(v.clone(), "close");
        assert_eq!(still_rejected.gap.path, r.gap.path);
        let c: Contract = serde_json::from_value(v.clone()).unwrap();
        let result = render_with_capabilities(&c).unwrap();
        let capability = result
            .capabilities
            .circuits
            .iter()
            .find(|x| x.name == "close")
            .unwrap();
        assert!(capability.recorded && capability.observed_call);
        assert!(capability.recording_unavailable.is_none());

        // Negation and point defaults are now supported; the private observation
        // preserves the exact old whole-root refusal independently.
        let expression = &mut circuit(&mut v, "guard")["actions"][index]["otherwise"]["value"];
        expression["left"]["kind"] = json!("hash_to_curve");
        expression["left"] = json!({"kind":"ec_neg", "value":expression["left"].clone()});
        expression["right"] = json!({"kind":"default", "ty":{"kind":"jubjub_point"}});
        let unsupported = rejected(v.clone(), "close");
        assert_eq!(unsupported.gap.path, r.gap.path);
        let c: Contract = serde_json::from_value(v.clone()).unwrap();
        let result = render_with_capabilities(&c).unwrap();
        let capability = result
            .capabilities
            .circuits
            .iter()
            .find(|x| x.name == "close")
            .unwrap();
        assert!(capability.recorded && capability.observed_call);
        // Fixed commitments are supported. This explicit opaque-input native-IR
        // control is frontend-excluded and retains concrete policy provenance.
        let expression = &mut circuit(&mut v, "guard")["actions"][index]["otherwise"]["value"];
        expression["left"] = json!({"kind":"hash_to_curve","value":{
            "kind":"persistent_commit","value":{"kind":"default","ty":{"kind":"opaque_string"}},
            "opening":{"kind":"bytes_literal","bytes":vec![0u8;32]}
        }});
        let still_rejected = rejected(v.clone(), "close");
        assert_eq!(still_rejected.gap.path, r.gap.path);
        let c: Contract = serde_json::from_value(v).unwrap();
        let result = render_with_capabilities(&c).unwrap();
        let capability = result
            .capabilities
            .circuits
            .iter()
            .find(|x| x.name == "close")
            .unwrap();
        assert!(!capability.recorded && !capability.observed_call);
        let gap = capability.recording_unavailable.as_ref().unwrap();
        // The historical shape refusal above is retained; publication names
        // the actual unsupported commitment inside the checked callee.
        assert_eq!(
            gap.code,
            crate::recorded::RecordingGapCode::UnsupportedExpression
        );
        assert_eq!(gap.ir_node, "Expr::PersistentCommit");
        assert_eq!(
            gap.path,
            format!("actions[0].callee[guard].actions[{index}].otherwise.value.left.value")
        );
    }
}

#[test]
